"""Recorded NASA artifacts; no new geometry is generated by these tests."""

import json
from pathlib import Path
import pytest
from data_pipeline.operations_cli import load_windows
from app.science.temporal_optimizer import RecordedProvider, optimize
from test_temporal_optimizer import config, changed


@pytest.mark.parametrize(
    "profile,requirements,status",
    [
        ("SOLAR_POWERED_EXPERIMENT", {"min_sun_visible_s": 3600}, "NOT_MET"),
        ("EARTH_DATA_TRANSMISSION", {"min_earth_continuous_s": 3600}, "MET"),
        ("SHORT_SURFACE_OBSERVATION", {"min_earth_continuous_s": 3600}, "MET"),
        (
            "CUSTOM_OPERATION",
            {"require_simultaneous": True, "min_joint_continuous_s": 1800},
            "NOT_MET",
        ),
    ],
)
def test_recorded_pilot(config, profile, requirements, status):
    w = load_windows("data_pipeline/evidence/command-07-windows.json")
    a = config.baseline_analysis.model_dump(exclude_unset=True)
    a["operation"] = {"profile": profile, "requirements": requirements}
    q = changed(config, baseline_analysis=a, max_detailed_candidates=1)
    r = optimize(q, RecordedProvider([w]))
    assert r.baseline.operation.decision.status == status
    assert r.baseline.operation.data_origin == "REAL_NASA_PROTOTYPE"
    assert r.baseline.operation.provenance["sources"] == w.source_evidence
    assert r.baseline.evidence_mode == "RECORDED"
    assert not r.recommendations
    if status == "MET":
        assert r.outcome == "KEEP_CURRENT_PLAN"


@pytest.mark.parametrize(
    "profile,requirements,outcome",
    [
        ("SOLAR_POWERED_EXPERIMENT", {"min_sun_visible_s": 3600}, "CANDIDATES_FOUND"),
        (
            "EARTH_DATA_TRANSMISSION",
            {"min_earth_continuous_s": 3600},
            "KEEP_CURRENT_PLAN",
        ),
        (
            "SHORT_SURFACE_OBSERVATION",
            {"min_earth_continuous_s": 3600},
            "KEEP_CURRENT_PLAN",
        ),
        (
            "CUSTOM_OPERATION",
            {"require_simultaneous": True, "min_joint_continuous_s": 1800},
            "CANDIDATES_FOUND",
        ),
    ],
)
def test_new_live_window_artifacts(profile, requirements, outcome):
    from app.science.window_models import WindowSearchResult
    from app.science.temporal_optimizer_models import TemporalOptimizationRequest
    from app.science.operations import evidence_identity

    artifact = json.loads(
        Path("data_pipeline/evidence/command-09-temporal-optimizer.json").read_text()
    )
    windows = [WindowSearchResult.model_validate(w) for w in artifact["live_windows"]]
    values = artifact["live_result"]["request"]
    values["baseline_analysis"]["operation"] = {
        "profile": profile,
        "requirements": requirements,
    }
    q = TemporalOptimizationRequest.model_validate(values)
    old = json.loads(Path("data_pipeline/evidence/command-07-windows.json").read_text())
    hint = WindowSearchResult.model_validate(
        old["extended_candidate_search"]["event_search"]
    )
    r = optimize(q, RecordedProvider(windows), hints=[hint])
    assert r.outcome == outcome
    c = next(c for c in r.candidates if c.operation)
    assert (
        c.operation.decision.status == "MET"
        and c.evidence_sha256 == evidence_identity(windows[1])
    )
    assert c.evidence_sha256 != r.baseline.evidence_sha256
    assert r.comparisons[0].validity == "EQUIVALENT_METHOD"
    assert (
        r.baseline.operation.provenance["sources"] == c.operation.provenance["sources"]
    )
    values["evaluation_policy"] = "STRICT_EVIDENCE"
    strict = TemporalOptimizationRequest.model_validate(values)
    assert not optimize(strict, RecordedProvider(windows), hints=[hint]).recommendations
